// Telegram hands back everything since next_offset and only forgets a message
// once we ask for the one after it, so the marker is advanced at the end of the
// run rather than here. Handling a message twice is harmless. Losing one is not.
const state = $('Load state').first().json;
const allow = new Map((state.allowlist || []).map(a => [String(a.telegram_user_id), a]));
const updates = ($input.first().json || {}).result || [];

const URL_RE = /https?:\/\/[^\s<>()]+/i;
let nextOffset = Number(state.next_offset) || 0;
const out = [];

for (const u of updates) {
  if (u.update_id >= nextOffset) nextOffset = u.update_id + 1;
  const msg = u.message;
  if (!msg || !msg.text) continue;

  const fromId = String(msg.from && msg.from.id);
  const who = allow.get(fromId) || null;
  const text = String(msg.text).trim();
  const found = text.match(URL_RE);
  const url = found ? found[0].replace(/[.,;:)\]]+$/, '') : null;
  // whatever the editor typed around the link: their own note, and the title
  // we fall back to when the page cannot be read
  const note = found ? text.replace(found[0], ' ').replace(/\s+/g, ' ').trim() : '';

  out.push({ json: {
    update_id: u.update_id,
    chat_id: msg.chat.id,
    from_id: fromId,
    from_name: [msg.from.first_name, msg.from.last_name].filter(Boolean).join(' '),
    allowed: !!who,
    text, url, note,
  }});
}

// Updates that carry nothing we handle still have to move the marker, or we
// would ask for them again every minute forever.
if (out.length === 0) {
  return updates.length ? [{ json: { skip: true, next_offset: nextOffset } }] : [];
}
for (const o of out) o.json.next_offset = nextOffset;
return out;

// Read the page for a title, so the editor does not have to type one.
//
// A page we cannot read leaves the editor's own words as the title instead.
// LinkedIn sits behind a login and lands here almost every time, and LinkedIn is
// the client's main social source, so this path is the normal one rather than
// the exception.
const m = $json;
if (m.skip || !m.allowed || !m.url) {
  return { json: { ...m, page_ok: false, title: null, publisher: null, published_at: null } };
}

const unescape = s => String(s)
  .replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#0?39;/g, "'")
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&nbsp;/g, ' ').trim();

let page_ok = false, pageTitle = null, publisher = null, published_at = null;
try {
  const html = String(await this.helpers.httpRequest({
    url: m.url, timeout: 15000, json: false,
    headers: { 'User-Agent': 'DFP newsletter bot (HAMK student project)' },
  }));
  const pick = re => { const x = html.match(re); return x ? unescape(x[1]) : null; };
  pageTitle = pick(/<meta[^>]+property=["']og:title["'][^>]+content=["']([^"']+)/i)
           || pick(/<title[^>]*>([^<]+)<\/title>/i);
  publisher = pick(/<meta[^>]+property=["']og:site_name["'][^>]+content=["']([^"']+)/i);
  published_at = pick(/<meta[^>]+property=["']article:published_time["'][^>]+content=["']([^"']+)/i);
  // A page that loads is not the same as an article we can read. LinkedIn
  // answers with its login page, title and all, so trusting that would file
  // "LinkedIn Login, Sign in" as the headline of whatever the editor meant.
  const LOGIN_LIKE = /(log ?in|sign ?in|sign ?up|kirjaudu|rekister|access denied|just a moment|are you a robot)/i;
  if (pageTitle && LOGIN_LIKE.test(pageTitle)) pageTitle = null;
  page_ok = !!pageTitle;
} catch (e) {
  page_ok = false;
}

return { json: { ...m, page_ok, publisher, published_at,
                 title: page_ok ? pageTitle : (m.note || null) } };

// Tell the editor what happened, in their words rather than ours.
const db = $json;                       // what the database did
const m  = $('Fetch page').item.json;   // the message it was about

let reply = null;
if (m.skip) {
  reply = null;
} else if (!m.allowed) {
  // Telling an unknown sender their own id is how someone gets added without a
  // round trip. It gives away nothing: they can read it from any bot.
  reply = `I only take links from people on the list.\n\nYour Telegram ID is ${m.from_id}. Send that to Vinh and he will add you.`;
} else if (!m.url) {
  reply = 'Send me a link and I will save it for the newsletter. You can put a note after the link.';
} else if (!m.page_ok && !m.note) {
  reply = 'I could not read that page. Send the link again with a title after it and I will save that instead.';
} else if (db.item_id) {
  reply = `Saved: ${m.title}`
        + (m.publisher ? `\n${m.publisher}` : '')
        + (m.page_ok ? '' : '\n(I could not read the page, so I used your own words as the title.)');
} else if (db.already_known) {
  reply = 'I already have that link.';
} else {
  reply = 'Something went wrong saving that. Try again, or tell Vinh.';
}

return { json: { ...m, reply, item_id: db.item_id ?? null, allowed_by_db: db.allowed } };

// Nothing to say for a message we did not act on.
const m = $json;
if (!m.reply) return { json: m };

await this.helpers.httpRequest({
  method: 'POST',
  url: `https://api.telegram.org/bot${$env.TELEGRAM_BOT_TOKEN}/sendMessage`,
  body: { chat_id: m.chat_id, text: m.reply, disable_web_page_preview: true },
  json: true,
});
return { json: m };

